'use strict';
(()=>{
 const $f=id=>document.getElementById(id),key='pulse-field-trades-v1',form=$f('field-form'),journal=$f('field-journal');if(!form||!journal)return;
 const setTime=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());$f('field-time').value=d.toISOString().slice(0,16)};setTime();
 let entries=[];try{const value=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(value))entries=value}catch{$f('field-message').textContent='Protokoll konnte nicht geladen werden.'}
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const format=n=>Number(n).toLocaleString('de-DE',{maximumFractionDigits:8});
 function pnl(e){return ((e.exit/e.entry-1)*(e.side==='short'?-1:1)*e.notional)-e.fees}
 function render(){ $f('field-count').textContent=entries.length+' Einträge';$f('field-rows').innerHTML=entries.length?entries.map(e=>`<tr><td>${escape(new Date(e.time).toLocaleString('de-DE'))}</td><td>${escape(e.symbol)}</td><td>${e.side==='short'?'Short':'Long'}</td><td>${format(e.entry)}</td><td>${format(e.exit)}</td><td class="${pnl(e)>=0?'positive':'negative'}">${pnl(e)>=0?'+':''}${format(pnl(e))} USDT</td><td>${escape(e.note)}</td><td><button type="button" class="field-delete" data-id="${escape(e.id)}" aria-label="Eintrag ${escape(e.symbol)} löschen">✕</button></td></tr>`).join(''):'<tr><td colspan="8" class="table-empty">Noch keine Einträge. Einträge sind nur hier im Browser sichtbar.</td></tr>'}
 function persist(next){try{localStorage.setItem(key,JSON.stringify(next));entries=next;render();return true}catch{$f('field-message').textContent='Speichern nicht möglich. Prüfe die Browser-Speichereinstellungen.';return false}}
 form.addEventListener('submit',event=>{event.preventDefault();const tradeTime=Date.parse($f('field-time').value),symbol=$f('field-symbol').value.trim().toUpperCase(),entry=Number($f('field-entry').value),exit=Number($f('field-exit').value),notional=Number($f('field-notional').value),fees=Number($f('field-fees').value),side=$f('field-side').value,note=$f('field-note').value.trim();if(!Number.isFinite(tradeTime)||!/^[A-Z0-9._-]{1,24}$/.test(symbol)||![entry,exit,notional,fees].every(Number.isFinite)||entry<=0||exit<=0||notional<=0||fees<0||!['long','short'].includes(side)){$f('field-message').textContent='Bitte gültiges Symbol, positive Kurse und Positionswert sowie nichtnegative Gebühren eingeben.';return}const e={id:Date.now()+'-'+Math.random().toString(36).slice(2),time:tradeTime,symbol,entry,exit,notional,fees,side,note};if(persist([e,...entries])){form.reset();setTime();$f('field-message').textContent='Eintrag gespeichert.'}});
 $f('field-rows').addEventListener('click',event=>{const button=event.target.closest('[data-id]');if(!button)return;if(!confirm('Diesen Feldtest-Eintrag löschen?'))return;if(persist(entries.filter(e=>e.id!==button.dataset.id)))$f('field-message').textContent='Eintrag gelöscht.'});
 $f('tradfi-list').addEventListener('click',event=>{const button=event.target.closest('[data-field-symbol]');if(!button)return;journal.querySelector('details').open=true;$f('field-symbol').value=button.dataset.fieldSymbol;$f('field-message').textContent='Symbol übernommen. Trage deine tatsächlichen Werte ein.';journal.scrollIntoView({behavior:'smooth',block:'start'});$f('field-entry').focus({preventScroll:true})});
 $f('field-export').addEventListener('click',()=>{if(!entries.length){$f('field-message').textContent='Noch keine Einträge für den Export.';return}const rows=[['Zeit UTC','Symbol','Richtung','Einstieg','Ausstieg','Positionswert USDT','Gebühren USDT','Ergebnis USDT Näherung','Notiz'],...entries.map(e=>[new Date(e.time).toISOString(),e.symbol,e.side,e.entry,e.exit,e.notional,e.fees,pnl(e),e.note])];const cell=v=>{let s=String(v);if(typeof v==='string'&&/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const csv='\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),link=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=link;a.download='pulse-feldtest.csv';a.click();setTimeout(()=>URL.revokeObjectURL(link),1000)});
 render();
})();
